create or replace function public.create_deployment_for_approved_change(p_change uuid,p_provider text default null) returns uuid language plpgsql security definer set search_path=public as $$ declare c public.change_requests;a boolean;bad boolean;d uuid;begin select * into c from public.change_requests where id=p_change and public.is_workspace_member(workspace_id);if c.id is null then raise exception 'change not found';end if;select exists(select 1 from public.approvals where change_request_id=p_change and status='approved') into a;select exists(select 1 from public.policy_evaluations where change_request_id=p_change and result='fail') into bad;if not a then raise exception 'approved decision required';end if;if bad then raise exception 'blocking policy failure';end if;select id into d from public.deployments where change_request_id=p_change and status in ('pending','running') order by created_at desc limit 1;if d is not null then return d;end if;insert into public.deployments(workspace_id,project_id,environment_id,change_request_id,validation_id,status,provider,started_at) values(c.workspace_id,c.project_id,c.environment_id,c.id,c.validation_id,'running',p_provider,now()) returning id into d;update public.change_requests set status='approved',updated_at=now() where id=p_change;insert into public.usage_events(workspace_id,user_id,project_id,event_type,quantity,metadata) values(c.workspace_id,auth.uid(),c.project_id,'deployment.execution',1,jsonb_build_object('deployment_id',d,'change_request_id',p_change));insert into public.audit_events(workspace_id,user_id,event_type,metadata) values(c.workspace_id,auth.uid(),'deployment.started',jsonb_build_object('deployment_id',d,'change_request_id',p_change));return d;end $$;
revoke all on function public.create_deployment_for_approved_change(uuid,text) from public,anon;grant execute on function public.create_deployment_for_approved_change(uuid,text) to authenticated;
create or replace function public.refresh_workspace_dora(p_workspace uuid) returns void language plpgsql security definer set search_path=public as $$ declare total_dep numeric;failed_dep numeric;freq numeric;lead numeric;mttr numeric;begin if not public.is_workspace_member(p_workspace) then raise exception 'forbidden';end if;select count(*)::numeric,count(*) filter(where status in ('failed','rolled_back'))::numeric into total_dep,failed_dep from public.deployments where workspace_id=p_workspace and created_at>=now()-interval '30 days';select coalesce(count(*)::numeric/30,0) into freq from public.deployments where workspace_id=p_workspace and status in ('completed','success','deployed') and created_at>=now()-interval '30 days';select coalesce(avg(extract(epoch from(coalesce(d.completed_at,now())-c.created_at))/3600),0) into lead from public.deployments d join public.change_requests c on c.id=d.change_request_id where d.workspace_id=p_workspace and d.status in ('completed','success','deployed') and d.created_at>=now()-interval '30 days';select coalesce(avg(extract(epoch from(i.resolved_at-i.created_at))/3600),0) into mttr from public.incidents i where i.workspace_id=p_workspace and i.resolved_at is not null and i.created_at>=now()-interval '30 days';insert into public.dora_metrics(workspace_id,metric_date,deployment_frequency,lead_time_hours,change_failure_rate,mttr_hours) values(p_workspace,current_date,round(freq,2),round(lead,2),case when total_dep=0 then 0 else round(failed_dep*100/total_dep,2) end,round(mttr,2)) on conflict(workspace_id,metric_date) do update set deployment_frequency=excluded.deployment_frequency,lead_time_hours=excluded.lead_time_hours,change_failure_rate=excluded.change_failure_rate,mttr_hours=excluded.mttr_hours;end $$;
revoke all on function public.refresh_workspace_dora(uuid) from public,anon;grant execute on function public.refresh_workspace_dora(uuid) to authenticated;